import{_ as l,a0 as t,w as o,s as d,ao as c,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Go 編程語言的簡單介紹 | LCTT x X-CMD","titleTemplate":false,"description":"Go 編程語言的簡單介紹 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Go 編程語言的簡單介紹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Go 編程語言的簡單介紹 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20181224 An Introduction to Go","title":"Go 編程語言的簡單介紹","tag":"201902","desc":""},"relativePath":"201902/20181224 An Introduction to Go.md","filePath":"[post].md"}'),r={name:"201902/20181224 An Introduction to Go.md"};function h(g,s,u,k,b,f){const n=t("Link");return o(),d("div",null,[s[18]||(s[18]=c(`<h1 id="go-編程語言的簡單介紹" tabindex="-1">Go 編程語言的簡單介紹 <a class="header-anchor" href="#go-編程語言的簡單介紹" aria-label="Permalink to “Go 編程語言的簡單介紹”">​</a></h1><p>（以下內容是我的碩士論文的摘錄，幾乎是整個 2.1 章節，向具有 CS 背景的人快速介紹 Go）</p><p>Go 是一門用於併發編程的命令式編程語言，它主要由創造者 Google 進行開發，最初主要由 Robert Griesemer、Rob Pike 和 Ken Thompson 開發。這門語言的設計起始於 2007 年，並在 2009 年推出最初版本；而第一個穩定版本是 2012 年發佈的 1.0 版本。[^1]</p><p>Go 有 C 風格的語法（沒有預處理器）、垃圾回收機制，而且類似它在貝爾實驗室裏被開發出來的前輩們：Newsqueak（Rob Pike）、Alef（Phil Winterbottom）和 Inferno（Pike、Ritchie 等人），使用所謂的 <ruby>Go 協程<rt>goroutines</rt></ruby>和<ruby>信道<rt>channels</rt></ruby>（一種基於 Hoare 的“通信順序進程”理論的協程）提供內建的併發支持。[^2]</p><p>Go 程序以包的形式組織。包本質是一個包含 Go 文件的文件夾。包內的所有文件共享相同的命名空間，而包內的符號有兩種可見性：以大寫字母開頭的符號對於其他包是可見，而其他符號則是該包私有的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>func PublicFunction() {</span></span>
<span class="line"><span>    fmt.Println(&quot;Hello world&quot;)</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>func privateFunction() {</span></span>
<span class="line"><span>    fmt.Println(&quot;Hello package&quot;)</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="類型" tabindex="-1">類型 <a class="header-anchor" href="#類型" aria-label="Permalink to “類型”">​</a></h3><p>Go 有一個相當簡單的類型系統：沒有子類型（但有類型轉換），沒有泛型，沒有多態函數，只有一些基本的類型：</p><ol><li><p>基本類型：<code>int</code>、<code>int64</code>、<code>int8</code>、<code>uint</code>、<code>float32</code>、<code>float64</code> 等</p></li><li><p><code>struct</code></p></li><li><p><code>interface</code>：一組方法的集合</p></li><li><p><code>map[K, V]</code>：一個從鍵類型到值類型的映射</p></li><li><p><code>[number]Type</code>：一些 Type 類型的元素組成的數組</p></li><li><p><code>[]Type</code>：某種類型的切片（具有長度和功能的數組的指針）</p></li><li><p><code>chan Type</code>：一個線程安全的隊列</p></li><li><p>指針 <code>*T</code> 指向其他類型</p></li><li><p>函數</p></li><li><p>具名類型：可能具有關聯方法的其他類型的別名（LCTT 譯註：這裏的別名並非指 Go 1.9 中的新特性“類型別名”）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type T struct { foo int }</span></span>
<span class="line"><span>type T *T</span></span>
<span class="line"><span>type T OtherNamedType</span></span></code></pre></div><p>具名類型完全不同於它們的底層類型，所以你不能讓它們互相賦值，但一些操作符，例如 <code>+</code>，能夠處理同一底層數值類型的具名類型對象們（所以你可以在上面的示例中把兩個 <code>T</code> 加起來）。</p></li></ol><p>映射、切片和信道是類似於引用的類型——它們實際上是包含指針的結構。包括數組（具有固定長度並可被拷貝）在內的其他類型則是值傳遞（拷貝）。</p><h4 id="類型轉換" tabindex="-1">類型轉換 <a class="header-anchor" href="#類型轉換" aria-label="Permalink to “類型轉換”">​</a></h4><p>類型轉換類似於 C 或其他語言中的類型轉換。它們寫成這樣子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TypeName(value)</span></span></code></pre></div><h4 id="常量" tabindex="-1">常量 <a class="header-anchor" href="#常量" aria-label="Permalink to “常量”">​</a></h4><p>Go 有“無類型”字面量和常量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1 // 無類型整數字面量</span></span>
<span class="line"><span>const foo = 1 // 無類型整數常量</span></span>
<span class="line"><span>const foo int = 1 // int 類型常量</span></span></code></pre></div><p>無類型值可以分為以下幾類：<code>UntypedBool</code>、<code>UntypedInt</code>、<code>UntypedRune</code>、<code>UntypedFloat</code>、<code>UntypedComplex</code>、<code>UntypedString</code> 以及 <code>UntypedNil</code>（Go 稱它們為基礎類型，其他基礎種類可用於具體類型，如 <code>uint8</code>）。一個無類型值可以賦值給一個從基礎類型中派生的具名類型；例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type someType int</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const untyped = 2 // UntypedInt</span></span>
<span class="line"><span>const bar someType = untyped // OK: untyped 可以被賦值給 someType</span></span>
<span class="line"><span>const typed int = 2 // int</span></span>
<span class="line"><span>const bar2 someType = typed // error: int 不能被賦值給 someType</span></span></code></pre></div><h3 id="接口和對象" tabindex="-1">接口和對象 <a class="header-anchor" href="#接口和對象" aria-label="Permalink to “接口和對象”">​</a></h3><p>正如上面所説的，接口是一組方法的集合。Go 本身不是一種面向對象的語言，但它支持將方法關聯到具名類型上：當聲明一個函數時，可以提供一個接收者。接收者是函數的一個額外參數，可以在函數之前傳遞並參與函數查找，就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type SomeType struct { ... }</span></span>
<span class="line"><span>type SomeType struct { ... }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>func (s *SomeType) MyMethod() {</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>func main() {</span></span>
<span class="line"><span>    var s SomeType</span></span>
<span class="line"><span>    s.MyMethod()</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果對象實現了所有方法，那麼它就實現了接口；例如，<code>*SomeType</code>（注意指針）實現了下面的接口 <code>MyMethoder</code>，因此 <code>*SomeType</code> 類型的值就能作為 <code>MyMethoder</code> 類型的值使用。最基本的接口類型是 <code>interface{}</code>，它是一個帶空方法集的接口 —— 任何對象都滿足該接口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type MyMethoder interface {</span></span>
<span class="line"><span>    MyMethod()</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>合法的接收者類型是有些限制的；例如，具名類型可以是指針類型（例如，<code>type MyIntPointer *int</code>），但這種類型不是合法的接收者類型。</p><h3 id="控制流" tabindex="-1">控制流 <a class="header-anchor" href="#控制流" aria-label="Permalink to “控制流”">​</a></h3><p>Go 提供了三個主要的控制了語句：<code>if</code>、<code>switch</code> 和 <code>for</code>。這些語句同其他 C 風格語言內的語句非常類似，但有一些不同：</p><ul><li>條件語句沒有括號，所以條件語句是 <code>if a == b {}</code> 而不是 <code>if (a == b) {}</code>。大括號是必須的。</li><li>所有的語句都可以有初始化，比如這個 <code>if result, err := someFunction(); err == nil { // use result }</code></li><li><code>switch</code> 語句在分支裏可以使用任何表達式</li><li><code>switch</code> 語句可以處理空的表達式（等於 <code>true</code>）</li><li>默認情況下，Go 不會從一個分支進入下一個分支（不需要 <code>break</code> 語句），在程序塊的末尾使用 <code>fallthrough</code> 則會進入下一個分支。</li><li>循環語句 <code>for</code> 不僅能循環值域：<code>for key, val := range map { do something }</code></li></ul><h3 id="go-協程" tabindex="-1">Go 協程 <a class="header-anchor" href="#go-協程" aria-label="Permalink to “Go 協程”">​</a></h3><p>關鍵詞 <code>go</code> 會產生一個新的 <ruby>Go 協程<rt>goroutine</rt></ruby>，這是一個可以並行執行的函數。它可以用於任何函數調用，甚至一個匿名函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>func main() {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    go func() {</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>    }()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    go some_function(some_argument)</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="信道" tabindex="-1">信道 <a class="header-anchor" href="#信道" aria-label="Permalink to “信道”">​</a></h3><p>Go 協程通常和<ruby>信道<rt>channels</rt></ruby>結合，用來提供一種通信順序進程的擴展。信道是一個併發安全的隊列，而且可以選擇是否緩衝數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var unbuffered = make(chan int) // 直到數據被讀取時完成數據塊發送</span></span>
<span class="line"><span>var buffered = make(chan int, 5) // 最多有 5 個未讀取的數據塊</span></span></code></pre></div><p>運算符 <code>&lt;-</code> 用於和單個信道進行通信。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>valueReadFromChannel := &lt;- channel</span></span>
<span class="line"><span>otherChannel &lt;- valueToSend</span></span></code></pre></div><p>語句 <code>select</code> 允許多個信道進行通信：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>select {</span></span>
<span class="line"><span>    case incoming := &lt;- inboundChannel:</span></span>
<span class="line"><span>    // 一條新消息</span></span>
<span class="line"><span>    case outgoingChannel &lt;- outgoing:</span></span>
<span class="line"><span>    // 可以發送消息</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="defer-聲明" tabindex="-1">defer 聲明 <a class="header-anchor" href="#defer-聲明" aria-label="Permalink to “defer 聲明”">​</a></h3><p>Go 提供語句 <code>defer</code> 允許函數退出時調用執行預定的函數。它可以用於進行資源釋放操作，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>func myFunc(someFile io.ReadCloser) {</span></span>
<span class="line"><span>    defer someFile.close()</span></span>
<span class="line"><span>    /* 文件相關操作 */</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>當然，它允許使用匿名函數作為被調函數，而且編寫被調函數時可以像平常一樣使用任何變量。</p><h3 id="錯誤處理" tabindex="-1">錯誤處理 <a class="header-anchor" href="#錯誤處理" aria-label="Permalink to “錯誤處理”">​</a></h3><p>Go 沒有提供異常類或者結構化的錯誤處理。然而，它通過第二個及後續的返回值來返回錯誤從而處理錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>func Read(p []byte) (n int, err error)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 內建類型：</span></span>
<span class="line"><span>type error interface {</span></span>
<span class="line"><span>    Error() string</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>必須在代碼中檢查錯誤或者賦值給 <code>_</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>n0, _ := Read(Buffer) // 忽略錯誤</span></span>
<span class="line"><span>n, err := Read(buffer)</span></span>
<span class="line"><span>if err != nil {</span></span>
<span class="line"><span>    return err</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>有兩個函數可以快速跳出和恢復調用棧：<code>panic()</code> 和 <code>recover()</code>。當 <code>panic()</code> 被調用時，調用棧開始彈出，同時每個 <code>defer</code> 函數都會正常運行。當一個 <code>defer</code> 函數調用 <code>recover()</code>時，調用棧停止彈出，同時返回函數 <code>panic()</code> 給出的值。如果我們讓調用棧正常彈出而不是由於調用 <code>panic()</code> 函數，<code>recover()</code> 將只返回 <code>nil</code>。在下面的例子中，<code>defer</code> 函數將捕獲 <code>panic()</code> 拋出的任何 <code>error</code> 類型的值並儲存在錯誤返回值中。第三方庫中有時會使用這個方法增強遞歸代碼的可讀性，如解析器，同時保持公有函數仍使用普通錯誤返回值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>func Function() (err error) {</span></span>
<span class="line"><span>    defer func() {</span></span>
<span class="line"><span>        s := recover()</span></span>
<span class="line"><span>        switch s := s.(type) {  // type switch</span></span>
<span class="line"><span>            case error:</span></span>
<span class="line"><span>                err = s         // s has type error now</span></span>
<span class="line"><span>            default:</span></span>
<span class="line"><span>                panic(s)</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="數組和切片" tabindex="-1">數組和切片 <a class="header-anchor" href="#數組和切片" aria-label="Permalink to “數組和切片”">​</a></h3><p>正如前邊説的，數組是值類型，而切片是指向數組的指針。切片可以由現有的數組切片產生，也可以使用 <code>make()</code> 創建切片，這會創建一個匿名數組以保存元素。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>slice1 := make([]int, 2, 5) // 分配 5 個元素，其中 2 個初始化為0</span></span>
<span class="line"><span>slice2 := array[:] // 整個數組的切片</span></span>
<span class="line"><span>slice3 := array[1:] // 除了首元素的切片</span></span></code></pre></div><p>除了上述例子，還有更多可行的切片運算組合，但需要明瞭直觀。</p><p>使用 <code>append()</code> 函數，切片可以作為一個變長數組使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>slice = append(slice, value1, value2)</span></span>
<span class="line"><span>slice = append(slice, arrayOrSlice...)</span></span></code></pre></div><p>切片也可以用於函數的變長參數。</p><h3 id="映射" tabindex="-1">映射 <a class="header-anchor" href="#映射" aria-label="Permalink to “映射”">​</a></h3><p><ruby>映射<rt>maps</rt></ruby>是簡單的鍵值對儲存容器，並支持索引和分配。但它們不是線程安全的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>someValue := someMap[someKey]</span></span>
<span class="line"><span>someValue, ok := someMap[someKey] // 如果鍵值不在 someMap 中，變量 ok 會賦值為 \`false\`</span></span>
<span class="line"><span>someMap[someKey] = someValue</span></span></code></pre></div>`,58)),p("p",null,[s[1]||(s[1]=a("[^1]: Frequently Asked Questions (FAQ) - The Go Programming Language ",-1)),e(n,{href:"https://golang.org/doc/faq#history"},{default:i(()=>[...s[0]||(s[0]=[a("https://golang.org/doc/faq#history",-1)])]),_:1}),s[2]||(s[2]=a(" [return] [^2]: HOARE, Charles Antony Richard. Communicating sequential processes. Communications of the ACM, 1978, 21. Jg., Nr. 8, S. 666-677. [return]",-1))]),s[19]||(s[19]=p("hr",null,null,-1)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"https://blog.jak-linux.org/2018/12/24/introduction-to-go/"},{default:i(()=>[...s[3]||(s[3]=[a("https://blog.jak-linux.org/2018/12/24/introduction-to-go/",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),e(n,{href:"https://blog.jak-linux.org/"},{default:i(()=>[...s[5]||(s[5]=[a("Julian Andres Klode",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),e(n,{href:"https://github.com/LazyWolfLin"},{default:i(()=>[...s[7]||(s[7]=[a("LazyWolfLin",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const v=l(r,[["render",h]]);export{C as __pageData,v as default};
